import {
  MeshBasicNodeMaterial,
  PlaneGeometry,
  Mesh,
  Group,
  DoubleSide,
} from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // --- Plane setup ---
  const width = 1.6;   // card width
  const height = 0.9;  // card height
  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({
    color: config.colors?.surface || '#0b0b10',
    side: DoubleSide,
    transparent: true,
  });
  const mesh = new Mesh(geometry, material);
  mesh.position.z = 0;   // plane at origin, text in front
  group.add(mesh);

  // --- Texture (if imageUrl provided) ---
  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        material.map = tex;
        material.needsUpdate = true;
        // Adjust plane aspect to match texture (keep height fixed)
        const aspect = tex.image ? tex.image.width / tex.image.height : 1;
        geometry.scale(aspect, 1, 1);
        // Re-center text if needed
        if (textMesh) {
          textMesh.position.x = 0; // keep centered
        }
      })
      .catch(() => {
        // fallback: leave flat color
      });
  }

  // --- Text ---
  const textContent =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];
  const headlineItem = textContent.find((t) => t.role === 'headline');
  const labelText = headlineItem?.text || 'Journal 3';
  const fontSize = headlineItem?.typography?.fontSize || 39;

  const textOpts = {
    fontSize: fontSize,
    color: config.colors?.paper || '#e8ecf2',
    align: 'center',
  };
  const textMesh = ctx.fontAtlas.createText(labelText, textOpts);
  if (textMesh) {
    textMesh.position.z = 0.01; // slightly in front of plane
    // Scale text to fit card width (approximate)
    const maxWidth = width * 0.8;
    const textWidth = textMesh.userData?.width || maxWidth; // may not exist
    const scale = maxWidth / textWidth;
    textMesh.scale.set(scale, scale, 1);
    group.add(textMesh);
  }

  // --- Interactions ---
  const hoverAnim = gsap.timeline({ paused: true, reversed: true });
  hoverAnim.to(group.position, {
    y: 0.15,
    duration: 0.4,
    ease: 'power2.out',
  });

  group.userData.handlers = {
    hover: {
      enter: () => hoverAnim.play(),
      leave: () => hoverAnim.reverse(),
    },
    click: {
      down: () => {
        gsap.to(group.scale, {
          x: 0.97,
          y: 0.97,
          z: 0.97,
          duration: 0.12,
          ease: 'back.out(1.7)',
        });
      },
      up: () => {
        gsap.to(group.scale, {
          x: 1,
          y: 1,
          z: 1,
          duration: 0.3,
          ease: 'power4.out',
        });
        ctx.emit('hub-journal.select', { label: labelText });
      },
    },
  };

  // --- Cleanup ---
  group.userData.cleanup = () => {
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(hoverAnim);
    hoverAnim.kill();
    material.dispose();
    geometry.dispose();
    // Text cleanup (if provided by library)
    if (textMesh && textMesh.userData.cleanup) {
      textMesh.userData.cleanup();
    }
    // Dispose texture if loaded
    if (material.map) material.map.dispose();
  };

  // The adapter will apply config.scenePosition, so we ignore it here.
  return group;
}
